    [TestMethod]
    public void FormatCurrency_StartsWithDollarSign()
    {
        var result = _formatter.FormatCurrency(9.99m);

        StringAssert.StartsWith(result, "$");
    }

    [TestMethod]
    public void FormatCurrency_EndsWith2DecimalPlaces()
    {
        var result = _formatter.FormatCurrency(5m);

        StringAssert.EndsWith(result, ".00");
    }

    [TestMethod]
    public void FormatCurrency_MatchesDecimalFormat()
    {
        var result = _formatter.FormatCurrency(1234.5m);

        StringAssert.Matches(result, new Regex(@"^\$\d+\.\d{2}$"));
        Assert.AreEqual("$1234.50", result);
    }

    [TestMethod]
    public void FormatCurrency_CustomSymbol()
    {
        var result = _formatter.FormatCurrency(42.00m, "€");

        StringAssert.StartsWith(result, "€");
        Assert.AreEqual("€42.00", result);
    }

    [TestMethod]
    public void FormatCurrency_NegativeAmount()
    {
        var result = _formatter.FormatCurrency(-10.50m);

        StringAssert.Contains(result, "-");
        Assert.AreEqual("$-10.50", result);
    }
}

